    static func elements(_ e: AXUIElement, _ a: String) -> [AXUIElement] { copy(e,a) as? [AXUIElement] ?? [] }
    static func actions(_ e: AXUIElement) -> [String] { var r: CFArray?; guard AXUIElementCopyActionNames(e,&r) == .success else{return []}; return r as? [String] ?? [] }
